    metadata: (json['metadata'] as Map<String, dynamic>).map((k, v) => MapEntry(k, v as String)),
    away: json['away'] == null ? null : json['away'] as String,
  );

  Map<String, dynamic> toJson() => {
    'nick': nick,
    'account': account,
    'modes': modes,
