    return switch (tag) {
      'privmsg' => MessageKindPrivmsg.fromJson(json),
      'notice' => MessageKindNotice.fromJson(json),
      'ctcp' => MessageKindCtcp.fromJson(json),
      'tagmsg' => MessageKindTagmsg.fromJson(json),
      'join' => MessageKindJoin.fromJson(json),
      'part' => MessageKindPart.fromJson(json),
      'quit' => MessageKindQuit.fromJson(json),
      'kick' => MessageKindKick.fromJson(json),
      'nick' => MessageKindNick.fromJson(json),
      'topic' => MessageKindTopic.fromJson(json),
      'mode' => MessageKindMode.fromJson(json),
      _ => throw ArgumentError.value(tag, 'type', 'unknown MessageKind variant'),
    };
  }
}

