/// A parsed protocol line.
/// The types are owned rather than borrowed from the input. A borrowed `Message<'a>` would parse
/// faster, but every consumer of this crate reaches it across a language boundary that cannot carry
/// a Rust lifetime, so the copy has to happen somewhere and here is the only place it happens once.
class RawMessage {
  const RawMessage({
    required this.tags,
    required this.source,
    required this.command,
    required this.params,
  });

  factory RawMessage.fromJson(Map<String, dynamic> json) => RawMessage(
    tags: (json['tags'] as List).map((e) => MessageTag.fromJson(e as Map<String, dynamic>)).toList(),
    source: json['source'] == null ? null : MessageSource.fromJson(json['source'] as Map<String, dynamic>),
    command: json['command'] as String,
    params: (json['params'] as List).map((e) => e as String).toList(),
  );

  Map<String, dynamic> toJson() => {
    'tags': tags.map((e) => e.toJson()).toList(),
    'source': source?.toJson(),
    'command': command,
    'params': params.map((e) => e).toList(),
  };

  /// The tag section, empty when the line carried no `@`.
  final MessageTags tags;

  /// The source, when the line carried one.
  final MessageSource? source;

  /// The command or three-digit numeric, as it arrived. Commands are case-insensitive on the wire,
  /// so compare with [`Message::is`] rather than `==`.
  final String command;

  /// The parameters, with the trailing parameter last and its `:` removed.
  final List<String> params;
}

/// What to authenticate with.
sealed class SaslCredentials {
  const SaslCredentials();

  Map<String, dynamic> toJson();

  factory SaslCredentials.fromJson(Map<String, dynamic> json) {
    final tag = json['mechanism'] as String;
    return switch (tag) {
      'plain' => SaslCredentialsPlain.fromJson(json),
      'external' => SaslCredentialsExternal.fromJson(json),
      'scram' => SaslCredentialsScram.fromJson(json),
      _ => throw ArgumentError.value(tag, 'mechanism', 'unknown SaslCredentials variant'),
    };
  }
}

