}

/// One participant's state within a [`Room`].
/// Every toggle is [`OnOff`] rather than `bool`: this is the same distinction clippy's own
/// `struct_excessive_bools` lint asks for (six independent flags read equally well as a state
/// machine's cases), and reusing `OnOff` rather than inventing six near-identical two-variant
/// enums keeps it to one type.
class VoiceParticipant {
  const VoiceParticipant({
    required this.nick,
    required this.role,
    required this.mic,
    required this.video,
    required this.speaking,
    required this.deaf,
    required this.screen,
    required this.hand,
  });

  factory VoiceParticipant.fromJson(Map<String, dynamic> json) => VoiceParticipant(
    nick: json['nick'] as String,
    role: VoiceRole.fromWire(json['role'] as String),
    mic: OnOff.fromWire(json['mic'] as String),
    video: OnOff.fromWire(json['video'] as String),
    speaking: OnOff.fromWire(json['speaking'] as String),
    deaf: OnOff.fromWire(json['deaf'] as String),
    screen: OnOff.fromWire(json['screen'] as String),
    hand: OnOff.fromWire(json['hand'] as String),
  );

  Map<String, dynamic> toJson() => {
    'nick': nick,
    'role': role.wire,
    'mic': mic.wire,
    'video': video.wire,
    'speaking': speaking.wire,
    'deaf': deaf.wire,
    'screen': screen.wire,
    'hand': hand.wire,
  };

  /// Their nick as the server spells it, since the map that holds them is keyed by a fold that
  /// throws that spelling away.
  final String nick;

  /// Whether they may publish, decided by the room kind and, in a `$` room, whether the
  /// server named them a streamer.
  final VoiceRole role;

  /// Microphone on.
  final OnOff mic;

  /// Camera on.
  final OnOff video;

  /// The voice-activity flag the last `presence` reported.
  final OnOff speaking;

  /// Not receiving room audio.
  final OnOff deaf;

  /// Screen share active.
  final OnOff screen;

  /// Hand raised.
  final OnOff hand;
}

/// The `state` a `presence` notification carries.
/// One wire `type: "presence"` actually carries three incompatible shapes: a membership change (`Joined`/`Left`), a toggle
/// (`On`/`Off`, read together with [`Signal::Presence`]'s `kind`), or an activity flag
/// (`Speaking`/`Silent`/`DeafOn`/`DeafOff`, which carries no `kind` at all).
enum VoicePresence {
  joined,
  left,
  on,
  off,
  speaking,
  silent,
  deaf_on,
  deaf_off;

  static VoicePresence fromWire(String wire) => VoicePresence.values.byName(wire);

  String get wire => name;
}

/// Whether a room participant may publish audio and video, or only receive it.
enum VoiceRole {
  publisher,
  viewer;

  static VoiceRole fromWire(String wire) => VoiceRole.values.byName(wire);

  String get wire => name;
}

/// The state of one voice room: who is in it, their kind of channel, and every participant's
/// mic, video, speaking, deaf, screen and hand state and role.
class VoiceRoom {
  const VoiceRoom({
    required this.channel,
    required this.kind,
    required this.participants,
    required this.turn,
  });

  factory VoiceRoom.fromJson(Map<String, dynamic> json) => VoiceRoom(
    channel: json['channel'] as String,
    kind: VoiceRoomKind.fromWire(json['kind'] as String),
    participants: (json['participants'] as Map<String, dynamic>).map((k, v) => MapEntry(k, VoiceParticipant.fromJson(v as Map<String, dynamic>))),
    turn: json['turn'] == null ? null : TurnCredentials.fromJson(json['turn'] as Map<String, dynamic>),
  );

  Map<String, dynamic> toJson() => {
    'channel': channel,
    'kind': kind.wire,
    'participants': participants.map((k, v) => MapEntry(k, v.toJson())),
    'turn': turn?.toJson(),
  };

  /// The channel this room's signalling is scoped to.
  final String channel;

  /// Whether every member publishes, or only the streamer and whoever they promote.
  final VoiceRoomKind kind;

  /// Every known participant, keyed by their folded nick.
  final Map<CaseFolded, VoiceParticipant> participants;

  /// The TURN credentials the SFU handed us on `joined`, if it has yet.
  final TurnCredentials? turn;
}

/// Who may publish in a voice room, decided by the channel's sigil.
enum VoiceRoomKind {
  publish,
  stream;

  static VoiceRoomKind fromWire(String wire) => VoiceRoomKind.values.byName(wire);

  String get wire => name;
}

/// One `+obsidianirc/rtc` signalling frame.
/// Every variant is one JSON object's `type`. The published
/// <https://github.com/obbyworld/extensions/blob/main/voice.md> documents only 9 of these, the
/// wire carries 19, and this enum follows the wire. Outbound intent and inbound notification are modelled as distinct shapes where the
/// wire actually distinguishes them (`mic`/`video`/`screen`/`hand`/`speaking`/`silent`/`deaf`
/// versus the `presence` they get rebroadcast as; `promote`/`demote` versus `role`), rather than
/// collapsed into one type as the published table's prose implies.
sealed class VoiceSignal {
  const VoiceSignal();

  Map<String, dynamic> toJson();

  factory VoiceSignal.fromJson(Map<String, dynamic> json) {
    final tag = json['type'] as String;
    return switch (tag) {
      'join' => VoiceSignalJoin.fromJson(json),
      'leave' => VoiceSignalLeave.fromJson(json),
      'joined' => VoiceSignalJoined.fromJson(json),
      'offer' => VoiceSignalOffer.fromJson(json),
      'answer' => VoiceSignalAnswer.fromJson(json),
      'ice' => VoiceSignalIce.fromJson(json),
      'presence' => VoiceSignalPresence.fromJson(json),
      'mic' => VoiceSignalMic.fromJson(json),
      'video' => VoiceSignalVideo.fromJson(json),
      'screen' => VoiceSignalScreen.fromJson(json),
      'hand' => VoiceSignalHand.fromJson(json),
      'deaf' => VoiceSignalDeaf.fromJson(json),
      'speaking' => VoiceSignalSpeaking.fromJson(json),
      'silent' => VoiceSignalSilent.fromJson(json),
      'react' => VoiceSignalReact.fromJson(json),
      'promote' => VoiceSignalPromote.fromJson(json),
      'demote' => VoiceSignalDemote.fromJson(json),
      'role' => VoiceSignalRole.fromJson(json),
      'error' => VoiceSignalError.fromJson(json),
      _ => throw ArgumentError.value(tag, 'type', 'unknown VoiceSignal variant'),
    };
  }
}

